const controlCard=(<div className="settings-card" role="region" aria-label="Browser control"><h2>Laya · reviewed control</h2><p>Commands → Laya · questions → Jarvis. Browser-only today; every action waits for your exact Confirm.</p><strong>{backend?.laya?.control_busy?'SETTING UP':backend?.browser?.enabled&&backend?.laya?.engine?.ready?'READY':'OFF'}</strong><p role="status">{backend?.laya?.control_busy?(backend?.laya?.setup?.busy?backend.laya.setup.status:backend.laya.status):backend?.laya?.status}</p>{backend?.laya?.error&&<p role="alert">{backend.laya.error}</p>}<button disabled={!connected||backend?.laya?.control_busy} onClick={()=>setControlReview(true)}>Enable browser control</button><button disabled={!connected} onClick={()=>{setControlReview(false);void command('browser-stop')}}>Stop browser control</button>{controlReview&&<div role="region" aria-label="Review browser control setup"><h3>Enable browser control?</h3><p>Verify existing files, download missing pinned Laya assets up to1.32GB, then load the CPU model using severalGB RAM. Allow your goals, public hostname and observed link labels to this local model. Stops the current reply and Mic for setup; turn Mic ON yourself afterwards. No browser window, navigation or microphone starts. Exact action Confirm stays required. Isolated Edge, not your ordinary Brave profile. No forms, sending, payments or file actions.</p><button onClick={()=>{setControlReview(false);void command('browser-enable',{consent:true})}}>Confirm browser control setup</button><button onClick={()=>setControlReview(false)}>Cancel browser control setup</button></div>}<p>Turn Mic ON and say "Laya, open the browser". Review the exact action here.</p>{view!=='Team'&&<button onClick={()=>navigate('Team')}>Back to Team room</button>}</div>);
