{intro&&<div className="startup-intro" role="status"><div className="intro-orbit">J</div><h2>JARVIS</h2><p>Your team. Your space.</p><button onClick={()=>setIntro(false)}>Skip intro</button></div>}<aside className="main-nav"><div className="brand"><span>J</span><div>JARVIS<small>YOUR TEAM. YOUR SPACE.</small></div></div><nav className="nav"><button className={view==='Chat'?'active':''} onClick={()=>navigate('Chat')}><Users size={18}/>Agents</button><button className={view==='Team'?'active':''} onClick={()=>navigate('Team')}><Users size={18}/>Team room</button><button aria-label="Settings" className={view==='Settings'?'active':''} onClick={()=>navigate('Settings')}><Settings size={18}/>Settings</button></nav><div className="chat-history-nav"><div><b>Chats</b><button disabled={!connected} onClick={()=>void command('history-new')}>New chat</button></div>{backend?.history_error&&<small role="alert">{backend.history_error}</small>}<div className="chat-list">{backend?.history?.map(chat=><div key={chat.id} className={chat.id===backend.chat_id?'active':''}><button disabled={backend?.busy||backend?.voice_active} title={chat.title} onClick={()=>{void command('history-open',{chat_id:chat.id});navigate('Chat')}}>{chat.title}</button><button aria-label={'Delete '+chat.title} disabled={backend?.busy||backend?.voice_active} onClick={()=>{if(window.confirm('Delete this saved conversation from this laptop? This cannot be undone here.'))void command('history-delete',{chat_id:chat.id,confirm:true})}}>×</button></div>)}</div></div><div className="nav-floating">{desktop&&<><button onClick={()=>void invoke('overlay')}>Transcript ON</button><button onClick={()=>void invoke('floating_off')}>Transcript OFF</button></>}</div><div className="bottom"><Shield size={16}/><span>Private until enabled<small>No sensors start on launch</small></span></div></aside>
<main><header><button className="back-button" aria-label="Previous view" onClick={back} disabled={!history.current.length}>←</button><h1>{view==='Chat'?'Agents':view==='Team'?'Team room':'Settings'}</h1><div className="status-chips"><span>MIC {backend?.voice_active?'on':'off'}</span><span>CAM {backend?.awareness.camera||'off'}</span><span>Cloud {backend?.brains?.slots.some(s=>s.enabled&&s.consent&&s.free)?'allowed':'off'}</span></div></header>
{desktop&&!connected&&<div className="connection-line"><span>Bundled core · secure local settings. LM Studio is optional.</span><button className="connect" onClick={()=>void connect()}>Connect bundled core</button></div>}
{connected&&<div className="connection-line"><span>Core connected · optional LM Studio {backend?.brains?.checks.local?.state||'not checked'} {backend?.brains?.checks.local?.error||backend?.brains?.checks.local?.model} · Cloud {backend?.brains?.slots.filter(s=>s.consent&&s.free).length||0} allowed slots</span><button onClick={()=>{setSettingsPane('Brain & APIs');navigate('Settings')}}>Brain connections</button></div>}
